const items = $input.all();

const isWebhook = items.some(item => item.json.headers !== undefined);
const mode = isWebhook ? 'webhook' : 'scheduled';

let dateFrom, dateTo;

if (isWebhook && items[0].json.body) {
  const body = items[0].json.body;
  dateFrom = body.dateFrom;
  dateTo = body.dateTo;
}

if (!dateFrom || !dateTo) {
  const now = new Date();
  const sevenDaysAgo = new Date(now);
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

  dateFrom = sevenDaysAgo.toISOString().split('T')[0];
  dateTo = now.toISOString().split('T')[0];
}

const testMode = isWebhook && items[0].json.body && items[0].json.body.mode === 'test';
const exportMode = isWebhook && items[0].json.body?.mode === 'export-json';
const shouldSendEmail = !testMode && !exportMode;
const customAlert = isWebhook ? (items[0].json.body?.customAlert || null) : null;

return [{
  json: {
    mode,
    testMode,
    shouldSendEmail,
    exportMode,
    dateFrom,
    dateTo,
    customAlert,
    executionTime: new Date().toISOString()
  }
}];

// Parse FOI RSS-flöde (direkt, utan sub-webhook)
const rssXml = typeof $json.data === 'string' ? $json.data : JSON.stringify($json);
const config = $('Detect Execution Mode').first().json;
const dateFrom = new Date(config.dateFrom);
const dateTo = new Date(config.dateTo);
dateTo.setHours(23, 59, 59, 999);

const reports = [];

try {
  const itemMatches = rssXml.matchAll(/<item>([\s\S]*?)<\/item>/g);

  for (const match of itemMatches) {
    const itemXml = match[1];

    const titleMatch = itemXml.match(/<title><!\[CDATA\[(.+?)\]\]><\/title>/) ||
                        itemXml.match(/<title>(.+?)<\/title>/);
    const linkMatch = itemXml.match(/<link><!\[CDATA\[(.+?)\]\]><\/link>/) ||
                       itemXml.match(/<link>(.+?)<\/link>/);
    const pubDateMatch = itemXml.match(/<pubDate>(.+?)<\/pubDate>/);
    const descMatch = itemXml.match(/<description><!\[CDATA\[([\s\S]+?)\]\]><\/description>/) ||
                       itemXml.match(/<description>([\s\S]+?)<\/description>/);

    if (titleMatch && linkMatch) {
      let pubDate = new Date();
      if (pubDateMatch) {
        pubDate = new Date(pubDateMatch[1]);
      }

      if (pubDate >= dateFrom && pubDate <= dateTo) {
        let description = descMatch ? descMatch[1] : '';
        description = description.replace(/<[^>]+>/g, '').trim().substring(0, 300);

        const url = linkMatch[1].startsWith('http')
          ? linkMatch[1]
          : `https://www.foi.se${linkMatch[1]}`;

        reports.push({
          source: 'FOI',
          type: 'report',
          title: titleMatch[1].trim(),
          url: url,
          date: pubDate.toISOString().split('T')[0],
          excerpt: description || titleMatch[1].trim()
        });
      }
    }
  }
} catch (e) {
  console.error('FOI RSS parse error:', e);
}

const limited = reports.slice(0, 10);
return limited.length > 0
  ? limited.map(r => ({ json: r }))
  : [{ json: { source: 'FOI', isEmpty: true } }];

const rssXml = $json.data;
const config = $('Detect Execution Mode').first().json;
const dateFrom = new Date(config.dateFrom);
const dateTo = new Date(config.dateTo);
dateTo.setHours(23, 59, 59, 999);

const posts = [];

try {
  const itemMatches = rssXml.matchAll(/<item>([\s\S]*?)<\/item>/g);

  for (const match of itemMatches) {
    const itemXml = match[1];

    const titleMatch = itemXml.match(/<title><!\[CDATA\[(.+?)\]\]><\/title>/) || itemXml.match(/<title>(.+?)<\/title>/);
    const linkMatch = itemXml.match(/<link>(.+?)<\/link>/);
    const pubDateMatch = itemXml.match(/<pubDate>(.+?)<\/pubDate>/);
    const descMatch = itemXml.match(/<description><!\[CDATA\[([\s\S]+?)\]\]><\/description>/) || itemXml.match(/<description>([\s\S]+?)<\/description>/);

    if (titleMatch && linkMatch && pubDateMatch) {
      const pubDate = new Date(pubDateMatch[1]);

      if (pubDate >= dateFrom && pubDate <= dateTo) {
        let description = descMatch ? descMatch[1] : '';
        description = description.replace(/<[^>]+>/g, '').substring(0, 300);

        posts.push({
          source: 'Carl Heath',
          type: 'blog',
          title: titleMatch[1],
          url: linkMatch[1],
          date: pubDate.toISOString().split('T')[0],
          excerpt: description
        });
      }
    }
  }
} catch (e) {
  console.error('RSS parse error:', e);
}

return posts.length > 0 ? posts.map(p => ({ json: p })) : [{ json: { source: 'Carl Heath', isEmpty: true } }];

const rssXml = $json.data;
const config = $('Detect Execution Mode').first().json;
const dateFrom = new Date(config.dateFrom);
const dateTo = new Date(config.dateTo);
dateTo.setHours(23, 59, 59, 999);

const posts = [];

try {
  const itemMatches = rssXml.matchAll(/<item>([\s\S]*?)<\/item>/g);

  for (const match of itemMatches) {
    const itemXml = match[1];

    const titleMatch = itemXml.match(/<title><!\[CDATA\[(.+?)\]\]><\/title>/) || itemXml.match(/<title>(.+?)<\/title>/);
    const linkMatch = itemXml.match(/<link>(.+?)<\/link>/);
    const pubDateMatch = itemXml.match(/<pubDate>(.+?)<\/pubDate>/);
    const descMatch = itemXml.match(/<description><!\[CDATA\[([\s\S]+?)\]\]><\/description>/) || itemXml.match(/<description>([\s\S]+?)<\/description>/);

    if (titleMatch && linkMatch && pubDateMatch) {
      const pubDate = new Date(pubDateMatch[1]);

      if (pubDate >= dateFrom && pubDate <= dateTo) {
        let description = descMatch ? descMatch[1] : '';
        description = description.replace(/<[^>]+>/g, '').substring(0, 300);

        posts.push({
          source: 'One Useful Thing',
          type: 'blog',
          title: titleMatch[1],
          url: linkMatch[1],
          date: pubDate.toISOString().split('T')[0],
          excerpt: description
        });
      }
    }
  }
} catch (e) {
  console.error('RSS parse error:', e);
}

return posts.length > 0 ? posts.map(p => ({ json: p })) : [{ json: { source: 'One Useful Thing', isEmpty: true } }];

// Max 5 kurerade artiklar per veckobrev
const MAX_CURATED_ARTICLES = 5;

const items = $input.all();
const config = $('Detect Execution Mode').first().json;
const dateFrom = new Date(config.dateFrom);
const dateTo = new Date(config.dateTo);
dateTo.setHours(23, 59, 59, 999);

const filteredItems = [];

items.forEach(item => {
  const row = item.json;
  if (!row.url || !row.title) return;

  let dateAdded;
  try {
    dateAdded = new Date(row.date_added);
    if (isNaN(dateAdded.getTime())) return;
  } catch (e) {
    return;
  }

  if (dateAdded >= dateFrom && dateAdded <= dateTo) {
    filteredItems.push({
      json: {
        url: row.url.trim(),
        title: row.title.trim(),
        category: row.category || '',
        dateAdded: row.date_added,
        sheetRowIndex: item.index + 2
      }
    });
  }
});

// Begränsa till max 5 artiklar (senaste först)
const limited = filteredItems
  .sort((a, b) => new Date(b.json.dateAdded) - new Date(a.json.dateAdded))
  .slice(0, MAX_CURATED_ARTICLES);

console.log('Kurerade artiklar: ' + filteredItems.length + ' hittade, ' +
  limited.length + ' inkluderas (max ' + MAX_CURATED_ARTICLES + ')');

return limited.length > 0
  ? limited
  : [{ json: { source: 'Curated Articles', isEmpty: true } }];

const items = $input.all();
const originalItems = $('Filter Active URLs').all();
const parsedArticles = [];

items.forEach((item, idx) => {
  if (item.json.isEmpty) {
    parsedArticles.push(item);
    return;
  }

  const originalData = originalItems[idx]?.json || {};

  if (item.error || !item.json) {
    parsedArticles.push({
      json: {
        source: 'Curated Articles',
        type: 'curated',
        title: originalData.title || 'Utan titel',
        url: originalData.url || '',
        date: originalData.dateAdded || '',
        category: originalData.category || '',
        excerpt: '[Artikelinnehall kunde inte hamtas]',
        error: true
      }
    });
    return;
  }

  let content = '';
  let excerpt = '';

  try {
    if (item.json.data && item.json.data.content) {
      content = item.json.data.content;
    } else if (typeof item.json === 'string') {
      content = item.json;
    } else if (item.json.content) {
      content = item.json.content;
    }

    excerpt = content
      .replace(/#+\s/g, '')
      .replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1')
      .replace(/\*\*/g, '')
      .replace(/\n\n+/g, ' ')
      .trim()
      .substring(0, 500);

    if (content.length > 500) excerpt += '...';
  } catch (e) {
    excerpt = '[Tolkningsfel]';
  }

  parsedArticles.push({
    json: {
      source: 'Curated Articles',
      type: 'curated',
      title: originalData.title || 'Utan titel',
      url: originalData.url || '',
      date: originalData.dateAdded || '',
      category: originalData.category || '',
      excerpt: excerpt || content.substring(0, 500),
      fullContent: content.substring(0, 2000),
      error: false
    }
  });
});

return parsedArticles;

// STRIKT FILTER: Endast citat fran senaste 7 dagarna
// Citat UTAN datum EXKLUDERAS (inte fallback till dagens datum)
const items = $input.all();

const now = new Date();
const sevenDaysAgo = new Date(now);
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
sevenDaysAgo.setHours(0, 0, 0, 0);

const quotes = [];

console.log('=== CITATFILTER ===');
console.log('Godkanner endast citat fran:', sevenDaysAgo.toISOString().split('T')[0],
  'till', now.toISOString().split('T')[0]);

items.forEach(item => {
  const row = item.json;

  const quoteVal = row.quote || row.Quote || row.citat || row.Citat || row.text || row.Text || '';
  const sourceVal = row.source || row.Source || row.kalla || row.Kalla || '';
  const contextVal = row.context || row.Context || row.kontext || row.Kontext || '';
  const urlVal = row.url || row.URL || row.Url || row.link || row.Link || '';
  const dateVal = (row.date_added || row['date_added '] || row.dateAdded || row.date || row.Date || row.datum || row.Datum || '').toString().trim();

  if (!quoteVal || !sourceVal) return;

  // STRIKT: Datum MASTE finnas
  if (!dateVal) {
    console.log('EXKLUDERAD (saknar datum):', sourceVal);
    return;
  }

  const dateAdded = new Date(dateVal);

  // STRIKT: Datum maste vara giltigt
  if (isNaN(dateAdded.getTime())) {
    console.log('EXKLUDERAD (ogiltigt datumformat):', sourceVal, '- varde:', dateVal);
    return;
  }

  // STRIKT: Maste vara inom senaste 7 dagarna
  if (dateAdded < sevenDaysAgo) {
    console.log('EXKLUDERAD (for gammalt):', sourceVal, '- datum:', dateVal);
    return;
  }

  if (dateAdded > now) {
    console.log('EXKLUDERAD (framtida):', sourceVal, '- datum:', dateVal);
    return;
  }

  quotes.push({
    json: {
      type: 'manual_quote',
      quote: quoteVal.trim(),
      source: sourceVal.trim(),
      context: contextVal || '',
      url: urlVal || '',
      dateAdded: dateAdded.toISOString().split('T')[0]
    }
  });
  console.log('GODKAND:', sourceVal, '- datum:', dateVal);
});

console.log('=== RESULTAT: ' + quotes.length + ' citat godkanda ===');

return quotes.length > 0 ? quotes : [{ json: { type: 'manual_quote', isEmpty: true } }];

// Parse Regeringen RSS-flode for nyheter om civilt forsvar/totalforsvar
const rssXml = $json.data || '';
const config = $('Detect Execution Mode').first().json;
const dateFrom = new Date(config.dateFrom);
const dateTo = new Date(config.dateTo);
dateTo.setHours(23, 59, 59, 999);

const posts = [];

try {
  const itemMatches = rssXml.matchAll(/<item>([\s\S]*?)<\/item>/g);

  for (const match of itemMatches) {
    const itemXml = match[1];

    // Hantera bade CDATA och vanlig text
    const titleMatch = itemXml.match(/<title><!\[CDATA\[(.+?)\]\]><\/title>/) || itemXml.match(/<title>(.+?)<\/title>/);
    const linkMatch = itemXml.match(/<link><!\[CDATA\[(.+?)\]\]><\/link>/) || itemXml.match(/<link>(.+?)<\/link>/);
    const pubDateMatch = itemXml.match(/<pubDate>(.+?)<\/pubDate>/);
    const descMatch = itemXml.match(/<description><!\[CDATA\[([\s\S]+?)\]\]><\/description>/) || itemXml.match(/<description>([\s\S]+?)<\/description>/);

    if (titleMatch && linkMatch) {
      let pubDate = new Date();
      if (pubDateMatch) {
        pubDate = new Date(pubDateMatch[1]);
      }

      // Filtrera pa datum
      if (pubDate >= dateFrom && pubDate <= dateTo) {
        let description = descMatch ? descMatch[1] : '';
        description = description.replace(/<[^>]+>/g, '').trim().substring(0, 300);

        posts.push({
          source: 'Regeringen',
          type: 'government',
          title: titleMatch[1].trim(),
          url: linkMatch[1].trim(),
          date: pubDate.toISOString().split('T')[0],
          excerpt: description || titleMatch[1].trim()
        });
      }
    }
  }
} catch (e) {
  console.error('Regeringen RSS parse error:', e);
}

const limited = posts.slice(0, 10);
return limited.length > 0 ? limited.map(p => ({ json: p })) : [{ json: { source: 'Regeringen', isEmpty: true } }];

const allItems = $input.all();

const response = {
  success: true,
  executionTime: new Date().toISOString(),
  sources: {
    foi: [],
    mcf: [],
    mtfa: [],
    regeringen: [],
    carlHeath: [],
    oneUsefulThing: [],
    curatedArticles: [],
    manualQuotes: []
  },
  totalItems: 0
};

allItems.forEach(item => {
  if (item.json.isEmpty) return;

  if (item.json.source === 'FOI') {
    response.sources.foi.push(item.json);
  } else if (item.json.source === 'MCF') {
    response.sources.mcf.push(item.json);
  } else if (item.json.source === 'MTFA') {
    response.sources.mtfa.push(item.json);
  } else if (item.json.source === 'Regeringen') {
    response.sources.regeringen.push(item.json);
  } else if (item.json.source === 'Carl Heath') {
    response.sources.carlHeath.push(item.json);
  } else if (item.json.source === 'One Useful Thing') {
    response.sources.oneUsefulThing.push(item.json);
  } else if (item.json.source === 'Curated Articles') {
    response.sources.curatedArticles.push(item.json);
  } else if (item.json.type === 'manual_quote') {
    response.sources.manualQuotes.push(item.json);
  }
});

response.totalItems = Object.values(response.sources).flat().length;

response.exportMode = !!$('Detect Execution Mode').first().json.exportMode;
return [{ json: response }];

// Prepare Synthesis Request v2
// Fixar: (1) Domänkunskap injiceras, (2) Föregående vecka som kontext,
// (3) Fast temataxonomi, (4) Bättre rekommendationsformat, (5) 8192 tokens
// (6) Läser från Enrich with Fulltext (som passerar genom berikad aggregerad data)

const aggregatedData = $input.first().json;
const config = $('Detect Execution Mode').first().json;

// === 1. DOMÄNKUNSKAP (var aldrig ansluten — nu fixat) ===
let domainContext = '';
try {
  domainContext = $('Build Domain Context').first().json.domainContext || '';
} catch (e) {
  console.log('Domänkunskap ej tillgänglig:', e.message);
}

// === 2. FÖREGÅENDE VECKAS NYHETSBREV (för de-duplikering och trender) ===
let previousWeekBlock = '';
let previousArticleUrls = [];
try {
  const prevResponse = $('Fetch Previous Newsletter').first().json;
  const results = prevResponse.results || [];

  if (results.length > 0) {
    const props = results[0].properties || {};

    // Sammanfattning
    const summaryParts = props.Sammanfattning?.rich_text || [];
    const prevSummary = summaryParts.map(p => p.text?.content || '').join('');

    // Teman
    const prevThemes = (props.Teman?.multi_select || []).map(t => t.name);

    // Period
    const periodParts = props.Period?.rich_text || [];
    const prevPeriod = periodParts.map(p => p.text?.content || '').join('');

    // Veckonummer
    const prevWeek = props.Vecka?.number || '?';

    if (prevSummary) {
      previousWeekBlock = [
        `=== FÖREGÅENDE VECKA (v${prevWeek}, ${prevPeriod}) ===`,
        `Sammanfattning: ${prevSummary}`,
        `Teman: ${prevThemes.join(', ')}`,
        ''
      ].join('\n');
    }

    // Extrahera titlar från föregående vecka för de-duplikering
    // (Egenskap-fältet innehåller sidtiteln)
    const titleParts = props.Egenskap?.title || [];
    const prevTitle = titleParts.map(p => p.text?.content || '').join('');
    if (prevTitle) {
      console.log('Föregående vecka:', prevTitle);
    }
  }
} catch (e) {
  console.log('Föregående vecka ej tillgänglig (normalt vid första körning):', e.message);
}

// === 3. FAST TEMATAXONOMI ===
const THEME_TAXONOMY = [
  'Hybridhot och informationspåverkan',
  'Totalförsvar och civilberedskap',
  'AI — säkerhet och möjligheter',
  'Cybersäkerhet och kritisk infrastruktur',
  'Geopolitik och säkerhetsordning',
  'Försörjningsberedskap och näringsliv',
  'Regional säkerhet (VG/Civo V)',
  'Demokrati och valpåverkan',
  'Maritim säkerhet och Östersjön',
  'Internationellt samarbete och Nato'
];

// === BYGG INNEHÅLLSSAMMANFATTNING (samma struktur, rensad) ===
let contentSummary = `Datumintervall: ${config.dateFrom} till ${config.dateTo}\n\n`;

contentSummary += `FOI RAPPORTER (${aggregatedData.sources.foi.length} dokument):\n`;
aggregatedData.sources.foi.forEach((item, i) => {
  contentSummary += `${i + 1}. ${item.title}\n` +
                    `   Datum: ${item.date}\n` +
                    (item.url ? `   URL: ${item.url}\n` : '') +
                    (item.excerpt ? `   Utdrag: ${item.excerpt}\n` : '') +
                    (item.fulltext ? `   --- FULLTEXT ---\n   ${item.fulltext}\n   --- SLUT FULLTEXT ---\n` : '') +
                    `\n`;
});

contentSummary += `\nMCF NYHETER (${aggregatedData.sources.mcf.length} nyheter):\n`;
aggregatedData.sources.mcf.forEach((item, i) => {
  contentSummary += `${i + 1}. ${item.title}\n` +
                    `   Datum: ${item.date}\n` +
                    (item.url ? `   URL: ${item.url}\n` : '') +
                    (item.excerpt ? `   Utdrag: ${item.excerpt}\n` : '') +
                    (item.fulltext ? `   --- FULLTEXT ---\n   ${item.fulltext}\n   --- SLUT FULLTEXT ---\n` : '') +
                    `\n`;
});

contentSummary += `\nMTFA ANALYSER (${aggregatedData.sources.mtfa.length} publikationer):\n`;
aggregatedData.sources.mtfa.forEach((item, i) => {
  contentSummary += `${i + 1}. ${item.title}\n` +
                    `   URL: ${item.url}\n\n`;
});

contentSummary += `\nREGERINGEN (${aggregatedData.sources.regeringen.length} nyheter):\n`;
aggregatedData.sources.regeringen.forEach((item, i) => {
  contentSummary += `${i + 1}. ${item.title}\n` +
                    `   Datum: ${item.date}\n` +
                    `   URL: ${item.url}\n` +
                    `   Utdrag: ${item.excerpt}\n\n`;
});

contentSummary += `\nCARL HEATH BLOGG (${aggregatedData.sources.carlHeath.length} inlagg):\n`;
aggregatedData.sources.carlHeath.forEach((item, i) => {
  contentSummary += `${i + 1}. ${item.title}\n` +
                    `   Datum: ${item.date}\n` +
                    `   URL: ${item.url}\n` +
                    `   Utdrag: ${item.excerpt}\n\n`;
});

contentSummary += `\nONE USEFUL THING (${aggregatedData.sources.oneUsefulThing.length} inlagg):\n`;
aggregatedData.sources.oneUsefulThing.forEach((item, i) => {
  contentSummary += `${i + 1}. ${item.title}\n` +
                    `   Datum: ${item.date}\n` +
                    `   URL: ${item.url}\n` +
                    `   Utdrag: ${item.excerpt}\n\n`;
});

contentSummary += `\nKURATERADE ARTIKLAR (${aggregatedData.sources.curatedArticles.length} artiklar):\n`;
aggregatedData.sources.curatedArticles.forEach((item, i) => {
  contentSummary += `${i + 1}. ${item.title}\n` +
                    `   Datum tillagd: ${item.date}\n` +
                    `   URL: ${item.url}\n` +
                    (item.category ? `   Kategori: ${item.category}\n` : '') +
                    `   Innehall: ${item.excerpt}\n` +
                    (item.fulltext ? `   --- FULLTEXT ---\n   ${item.fulltext}\n   --- SLUT FULLTEXT ---\n` : '') +
                    `\n`;
});

contentSummary += `\nMANUELLT TILLAGDA CITAT (${aggregatedData.sources.manualQuotes.length} st):\n`;
aggregatedData.sources.manualQuotes.forEach((item, i) => {
  contentSummary += `${i + 1}. "${item.quote}"\n` +
                    `   Kalla: ${item.source}\n` +
                    (item.context ? `   Kontext: ${item.context}\n` : '') +
                    (item.url ? `   URL: ${item.url}\n` : '') +
                    `\n`;
});

// === BYGG SYSTEMPROMPT ===
const systemPrompt = `Du ar en strategisk analytiker for Länsstyrelsen i Västra Götaland med expertis inom civilforsvar, krishantering och AI-teknologi.

Fokusomraden:
- Civilforsvar och totalforsvar
- AI-sakerhet och robusthet
- Krishantering och samhallsskydd
- Desinformation och informationssakerhet
- Kritisk infrastruktur
- Beredskap och resiliens

${domainContext ? `\n${domainContext}\n` : ''}
${previousWeekBlock ? `\n${previousWeekBlock}\n` : ''}

=== TEMATAXONOMI (OBLIGATORISK) ===
Valj EXAKT bland dessa 10 teman. Anvand deras exakta namn. Valj max 4 per vecka.
${THEME_TAXONOMY.map((t, i) => `${i + 1}. ${t}`).join('\n')}

=== REGLER ===
1. Anvand ENDAST information fran underlaget. Hitta inte pa kallor.
2. Inkludera alla manuellt tillagda citat (markera med isManual: true).
3. Citat: Inkludera ENDAST nya uttalanden fran datumintervallet. Exkludera gamla citat som artiklar refererar till.
4. Kurerade artiklar: Inkludera ALLA (upp till 5) i curatedArticleInsights med keyTakeaway pa 1-2 meningar.
5. FOI/MCF/MTFA: Inkludera de mest relevanta (upp till 5) i foiAndMcfReports. MTFA-publikationer ska inkluderas här.
6. Regeringen: Inkludera de mest relevanta (upp till 5) i regeringenNews.
7. Teman: Valj EXAKT fran taxonomin ovan. Inga egna temanamn.
8. Rekommendationer: Var KONKRET — ange vad som ska goras och koppling till Lansstyrelsens uppdrag.
${previousWeekBlock ? '9. TRENDANALYS: Jamfor med foregaende vecka. Ange for varje tema om det ar Nytt / Pagaende / Eskalerande / Avklingande.\n10. DE-DUPLIKERING: Om en artikel eller ett citat redan fanns i foregaende veckas rapport, inkludera den INTE igen.' : ''}

Returnera ditt svar som ENBART ett JSON-objekt (ingen annan text, inga markdown-block) med foljande struktur:

{
  "executiveSummary": "Kort sammanfattning (3-5 meningar) av veckans viktigaste utveckling",
  "curatedArticleInsights": [
    {
      "title": "Artikeltitel",
      "url": "URL",
      "category": "Kategori",
      "keyTakeaway": "1-2 meningar om huvudpoangen"
    }
  ],
  "keyQuotes": [
    {
