// Parse Synthesis Response v2
// Uppdaterad for att hantera nytt recommendations-format (objekt istallet for strang)

const claudeResponse = $json;
const sourceData = $('Prepare Synthesis Request').first().json.sourceData;

try {
  const aiText = claudeResponse.content[0].text.trim();

  let cleanText = aiText;
  if (cleanText.startsWith('```')) {
    cleanText = cleanText.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
  }

  let insights;
  try {
    insights = JSON.parse(cleanText);
  } catch (parseError) {
    const jsonMatch = cleanText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        insights = JSON.parse(jsonMatch[0]);
      } catch (e) {
        insights = {
          executiveSummary: 'Kunde inte parsa AI-svaret korrekt.',
          themes: [],
          keyQuotes: [],
          recommendations: [],
          curatedArticleInsights: [],
          foiAndMcfReports: [],
          regeringenNews: []
        };
      }
    } else {
      insights = {
        executiveSummary: cleanText.substring(0, 500),
        themes: [],
        keyQuotes: [],
        recommendations: [],
        curatedArticleInsights: [],
        foiAndMcfReports: [],
        regeringenNews: []
      };
    }
  }

  // Sakerstall att alla falt finns
  insights.themes = insights.themes || [];
  insights.keyQuotes = insights.keyQuotes || [];
  insights.recommendations = insights.recommendations || [];
  insights.curatedArticleInsights = insights.curatedArticleInsights || [];
  insights.foiAndMcfReports = insights.foiAndMcfReports || [];
  insights.regeringenNews = insights.regeringenNews || [];

  // Normalisera recommendations: hantera bade string[] och object[]
  insights.recommendations = insights.recommendations.map(r => {
    if (typeof r === 'string') return r;
    if (r && r.action) return r; // Nytt objekt-format — behall
    return String(r);
  });

  return [{
    json: {
      success: true,
      executionTime: sourceData.executionTime,
      sourceData: sourceData.sources,
      aiInsights: insights,
      metadata: {
        model: 'claude-sonnet-4-20250514',
        tokensUsed: claudeResponse.usage
      }
    }
  }];

} catch (error) {
  return [{
    json: {
      success: false,
      error: error.message,
      executionTime: sourceData.executionTime,
      sourceData: sourceData.sources,
      aiInsights: {
        executiveSummary: 'Fel vid AI-analys: ' + error.message,
        themes: [],
        keyQuotes: [],
        recommendations: [],
        curatedArticleInsights: [],
        foiAndMcfReports: [],
        regeringenNews: []
      }
    }
  }];
}

