 function cleanForSpeech(text) {
   return text
     // Ta bort style-block helt (inklusive innehåll)
     .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
     // Ta bort script-block helt
     .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
     // Ta bort head-block helt
     .replace(/<head[^>]*>[\s\S]*?<\/head>/gi, '')
     // Ta bort HTML-kommentarer
     .replace(/<!--[\s\S]*?-->/g, '')
     // Ta bort alla HTML-taggar
     .replace(/<[^>]*>/g, '')
     // Ta bort markdown bold/italic
     .replace(/\*\*(.*?)\*\*/g, '$1')
     .replace(/\*(.*?)\*/g, '$1')
     // Ta bort markdown headers
     .replace(/#{1,6}\s*/g, '')
     // Ta bort markdown listor
     .replace(/^[\s]*[-*+]\s+/gm, '')
     // Ta bort markdown länkar, behåll texten
     .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
     // Ta bort URLs
     .replace(/https?:\/\/\S+/g, '')
     // Ta bort e-postadresser
     .replace(/[\w.-]+@[\w.-]+\.\w+/g, '')
     // Ersätt HTML-entities
     .replace(/&nbsp;/g, ' ')
     .replace(/&amp;/g, '&')
     .replace(/&lt;/g, '<')
     .replace(/&gt;/g, '>')
     .replace(/&quot;/g, '"')
     // Normalisera radbrytningar och whitespace
     .replace(/\n{3,}/g, '\n\n')
     .replace(/\s+/g, ' ')
     .trim();
 }

 function getWeekNumber(date) {
   const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
   d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
   const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
   return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
 }

 function estimateDuration(text) {
   const wordCount = text.split(/\s+/).length;
   return Math.ceil(wordCount / 150);
 }

