function getWeekNumber(dateStr) {
  const d = new Date(dateStr);
  const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  t.setUTCDate(t.getUTCDate() + 4 - (t.getUTCDay() || 7));
  const y = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
  return Math.ceil((((t - y) / 86400000) + 1) / 7);
}

// Matcha Claude-genererat temanamn mot taxonomin (fuzzy match)
function matchTheme(generatedName) {
  const lower = generatedName.toLowerCase();

  // Exakt match först
  const exact = VALID_THEMES.find(t => t.toLowerCase() === lower);
  if (exact) return exact;

  // Nyckelords-match
  const keywordMap = {
    'hybrid': 'Hybridhot och informationspåverkan',
    'desinformation': 'Hybridhot och informationspåverkan',
    'informationspåverkan': 'Hybridhot och informationspåverkan',
