// Parse MTFA publikationer via Jina Reader markdown
 const response = $json;
 const config = $('Detect Execution Mode').first().json;
 const dateFrom = new Date(config.dateFrom);
 const dateTo = new Date(config.dateTo);
 dateTo.setHours(23, 59, 59, 999);

 const publications = [];

 try {
   let content = '';
   if (response.data && response.data.content) {
     content = response.data.content;
   } else if (typeof response === 'string') {
     content = response;
   } else if (response.content) {
     content = response.content;
   }

   if (!content) {
     return [{ json: { source: 'MTFA', isEmpty: true } }];
   }

   // MTFA publikationssida har typiskt titlar som markdown-rubriker
   // och länkar till individuella publikationer
   const lines = content.split('\n');
   let currentTitle = '';
   let currentUrl = '';
   let currentExcerpt = '';

   for (const line of lines) {
     // Fånga rubriker (## eller ###)
     const headerMatch = line.match(/^#{2,3}\s+\[?(.+?)\]?\(?([^)]*)\)?$/);
     if (headerMatch) {
       // Spara föregående om den finns
       if (currentTitle && currentUrl) {
         publications.push({
           source: 'MTFA',
           type: 'analysis',
           title: currentTitle,
           url: currentUrl.startsWith('http') ? currentUrl : `https://www.mtfa.se${currentUrl}`,
           date: new Date().toISOString().split('T')[0],
           excerpt: currentExcerpt.trim().substring(0, 300)
         });
         currentExcerpt = '';
       }
       currentTitle = headerMatch[1].trim();
       currentUrl = headerMatch[2] || '';
       continue;
     }

     // Fånga markdown-länkar: [titel](url)
     const linkMatch = line.match(/\[([^\]]+)\]\(([^)]+publikationer[^)]*)\)/);
     if (linkMatch && !currentUrl) {
       currentTitle = linkMatch[1].trim();
       currentUrl = linkMatch[2];
       continue;
     }

     // Alternativ: fånga alla länkar till mtfa.se/publikationer/
     const mtfaLinkMatch = line.match(/\[([^\]]+)\]\(((?:https?:\/\/(?:www\.)?mtfa\.se)?\/publikationer\/[^)]+)\)/);
     if (mtfaLinkMatch) {
       if (currentTitle && currentUrl) {
         publications.push({
           source: 'MTFA',
           type: 'analysis',
           title: currentTitle,
           url: currentUrl.startsWith('http') ? currentUrl : `https://www.mtfa.se${currentUrl}`,
           date: new Date().toISOString().split('T')[0],
           excerpt: currentExcerpt.trim().substring(0, 300)
         });
       }
       currentTitle = mtfaLinkMatch[1].trim();
       currentUrl = mtfaLinkMatch[2];
       currentExcerpt = '';
       continue;
     }

     // Samla beskrivningstext
     if (currentTitle && line.trim() && !line.startsWith('#') && !line.startsWith('---')) {
       currentExcerpt += ' ' + line.trim();
     }
   }

   // Spara sista
   if (currentTitle && currentUrl) {
     publications.push({
       source: 'MTFA',
       type: 'analysis',
       title: currentTitle,
       url: currentUrl.startsWith('http') ? currentUrl : `https://www.mtfa.se${currentUrl}`,
       date: new Date().toISOString().split('T')[0],
       excerpt: currentExcerpt.trim().substring(0, 300)
     });
   }
 } catch (e) {
   console.error('MTFA parse error:', e);
 }

 // MTFA publicerar sällan — ta max 5 senaste
 const limited = publications.slice(0, 5);
 return limited.length > 0
   ? limited.map(p => ({ json: p }))
   : [{ json: { source: 'MTFA', isEmpty: true } }];

// Format MCF RSS — ersatter HTML-skrapning
// Placeras i en Code-nod efter "Fetch MCF News (RSS)"
// Matchar det format som Aggregate All Results forvantar
// Inget datumfilter — Claude avgör relevans

const items = $input.all();

// Max 10 artiklar fran RSS-flödet
const limited = items.slice(0, 10);

if (limited.length === 0) {
