  }
}));

// Enrich with Fulltext — hamtar artikeltext via Jina Reader
// Placeras MELLAN Aggregate All Results och Prepare Synthesis Request
// Hanterar paywalls: kort innehall eller inloggningsfragor = hoppa over

const aggregatedData = $input.first().json;
const sources = aggregatedData.sources;

// === VALJ ARTIKLAR FOR FULLTEXT (max 5 totalt) ===
const candidates = [];

// 1. Kurerade artiklar — handplockade, hogst prio (alla)
(sources.curatedArticles || []).forEach((a, i) => {
  if (a.url && a.title) {
    candidates.push({ key: 'curatedArticles', idx: i, url: a.url, title: a.title });
  }
});

// 2. FOI-rapporter — oppen tillgang, max 2
(sources.foi || []).slice(0, 2).forEach((a, i) => {
  if (a.url && a.title) {
    candidates.push({ key: 'foi', idx: i, url: a.url, title: a.title });
  }
});

// 3. MCF-nyheter — myndighetssida, oppen tillgang, max 2
(sources.mcf || []).slice(0, 2).forEach((a, i) => {
  if (a.url && a.title) {
    candidates.push({ key: 'mcf', idx: i, url: a.url, title: a.title });
  }
});

const toFetch = candidates.slice(0, 5);
let successCount = 0;
let paywallCount = 0;

// === HAMTA FULLTEXT VIA JINA READER ===
for (const c of toFetch) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://r.jina.ai/${c.url}`,
      headers: {
        'Accept': 'text/plain',
        'X-No-Cache': 'true'
      },
      timeout: 10000,
    });

    const content = typeof response === 'string' ? response : '';

    // Paywall-detektion: kort svar eller inloggningsuppmaningar
    const first500 = content.substring(0, 500).toLowerCase();
    const isPaywall =
      content.length < 200 ||
      /prenumerera|subscribe|logga in|sign.?in|paywall|skapa.?konto|create.?account|cookies.?m.ste|accept cookies/i.test(first500);

    if (!isPaywall && content.length >= 200) {
      // Rensa och begransa till 3000 tecken
      const cleaned = content
        .replace(/\n{3,}/g, '\n\n')           // Ta bort overflodiga radbrytningar
        .replace(/^\s*[-*]\s*$/gm, '')          // Ta bort tomma listpunkter
        .replace(/!\[.*?\]\(.*?\)/g, '')        // Ta bort bildllankar
        .trim()
        .substring(0, 3000);

      sources[c.key][c.idx].fulltext = cleaned;
      successCount++;
      console.log(`Fulltext OK: ${c.title} (${cleaned.length} tecken)`);
    } else {
      paywallCount++;
      console.log(`Paywall/kort: ${c.title} (${content.length} tecken)`);
    }
  } catch (e) {
    console.log(`Fulltext FEL: ${c.title}: ${e.message}`);
    // Tyst felhantering — behal original excerpt
  }

  // 500ms paus mellan anrop (artighet mot Jina)
  await new Promise(resolve => setTimeout(resolve, 500));
}

console.log(`Fulltext: ${successCount}/${toFetch.length} lyckades, ${paywallCount} paywall`);

// === RETURNERA BERIKAD DATA ===
return [{
  json: {
    ...aggregatedData,
    fulltextStats: {
      attempted: toFetch.length,
      succeeded: successCount,
      paywallBlocked: paywallCount
    }
  }
}];
